import {roster,getFighter} from './roster.js';
import {drawFinisherScene,FINISHER_DURATION,finisherProfile} from './finisher-scenes.js';
import {drawFighter} from './realistic-art.js';
import {reducedMotion} from './preferences.js';
const images=new Map();function image(id){if(!images.has(id)){const img=new Image();img.src='assets/sprites/'+id+'.png?v=20261020-6';images.set(id,img);while(images.size>4)images.delete(images.keys().next().value)}return images.get(id)}
let dialog,frame=0,progress=0,playing=false,last=0,id='lula';
export function openFinisherPreview(fighterId){id=fighterId;window.dispatchEvent(new Event('brasa:modal'));if(!dialog){dialog=document.createElement('dialog');dialog.className='finisher-preview';dialog.setAttribute('aria-label','Prévia das finalizações');dialog.innerHTML=`<div class="finisher-preview-tools"><label>PERSONAGEM <select aria-label="Personagem da finalização">${roster.map(f=>`<option value="${f.id}">${f.name}</option>`).join('')}</select></label><button data-play>REPRODUZIR</button><button data-close aria-label="Fechar prévia">✕</button></div><canvas width="1280" height="620" aria-label="Cena da finalização"></canvas><label class="finisher-preview-timeline">CENA <input aria-label="Posição da finalização" type="range" min="0" max="100" value="0"></label><p></p>`;document.body.append(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{cancelAnimationFrame(frame);frame=0;playing=false});dialog.querySelector('select').onchange=e=>{id=e.target.value;reset()};dialog.querySelector('input').oninput=e=>{playing=false;progress=+e.target.value/100;paint();state()};dialog.querySelector('[data-play]').onclick=()=>{if(progress>=.99)progress=0;playing=!playing;state()}}dialog.querySelector('select').value=id;reset();dialog.showModal();frame=requestAnimationFrame(tick)}
function state(){dialog.querySelector('[data-play]').textContent=playing?'PAUSAR':'REPRODUZIR'}
function reset(){progress=0;playing=true;image(id);image(id==='lula'?'flavio':'lula');dialog.querySelector('p').textContent=finisherProfile(id).description+' Referência criativa: '+finisherProfile(id).basis+'. Falas e ações são paródia.';state()}
function paint(){const c=dialog.querySelector('canvas').getContext('2d'),winner={data:getFighter(id),facing:1,index:0},loser={data:getFighter(id==='lula'?'flavio':'lula'),facing:-1,index:1},draw=(ctx,f,x,y)=>{ctx.save();ctx.translate(x,y-510);drawFighter(ctx,{...f,x:0},image(f.data.id),0,290);ctx.restore()};drawFinisherScene(c,{winner,loser,progress,reduced:reducedMotion(),drawWinner:draw,drawLoser:draw});dialog.querySelector('input').value=Math.round(progress*100)}
function tick(time){if(!dialog.open)return;const dt=Math.min(.05,(time-last)/1000||0);last=time;if(playing){progress=Math.min(1,progress+dt/FINISHER_DURATION);if(progress===1){playing=false;state()}}paint();frame=requestAnimationFrame(tick)}
